/**
 * The shader runtime — one implementation, shared by every surface.
 *
 * This file is framework-free on purpose. Three very different callers need
 * to put a shader on screen and they must not each get their own copy:
 *
 *   ShaderSurface        the React component a buyer pastes into their app
 *   <ShaderRuntime/>     the DOM scanner that boots the catalog's previews,
 *                        wherever `dangerouslySetInnerHTML` dropped a canvas
 *   scripts/shot-*       the screenshot harness, which drives it headless
 *
 * The catalog injects effect markup as a string — that is how all 1,047 CSS
 * effects render, on cards this page never knew about. A shader effect's
 * markup is therefore also a string, and what it contains is a `<canvas
 * data-hoverlab-shader="aurora">`. Something has to find those canvases and
 * start them. That something calls `mountShader`, and so does the React
 * component, so preview and product cannot drift.
 *
 * SHIPPED FILE. This is one of the three files a buyer copies (see
 * `scripts/build-shader-sources.mts`), which is why it imports nothing.
 */

/* ------------------------------------------------------------------ *
 *  Program types
 * ------------------------------------------------------------------ */

/**
 * The four colours every program is given, as CSS hex.
 *
 * A shader that hardcodes its colours can only look right on one
 * background, and the catalog's standing rule is that an effect holds up in
 * both themes. Rather than trust that per design, the contract removes the
 * choice: a program gets `u_c0`, `u_c1`, `u_c2` and `u_bg` and may not name
 * a colour of its own. Switching theme swaps four vec3s and redraws — it
 * does not recompile, and it cannot miss a stray `vec3(0.1)` in a highlight.
 */
export interface ShaderPalette {
  /** Primary — the colour a visitor would name if asked what this is. */
  c0: string
  /** Secondary: the second band, the other ball, the far end of a ramp. */
  c1: string
  /** Accent, used sparingly — rims, sparks, the hot centre. */
  c2: string
  /** The surface the effect sits on. Also what the CSS fallback paints. */
  bg: string
}

interface ProgramBase {
  /** Matches the catalog id and the `data-hoverlab-shader` attribute. */
  id: string
  light: ShaderPalette
  dark: ShaderPalette
  /**
   * Multiplier on `u_time`. Authored per design rather than baked into the
   * shader, so one number is what a slider moves and what the
   * reduced-motion path freezes.
   */
  speed?: number
  /**
   * Whether the design reads `u_pointer`. Opt-in: tracking costs a
   * `pointermove` listener per surface, and most designs never read it.
   */
  pointer?: boolean
  /**
   * The moment a reduced-motion surface is frozen at, in seconds.
   *
   * Defaults to `STILL_TIME`, which is late enough that every continuous
   * design has settled into what it actually is. Designs with discrete
   * events override it: lightning is dark between strikes, so freezing it
   * at an arbitrary second has a good chance of showing an empty sky, and
   * "reduced motion" does not mean "shown nothing".
   */
  stillTime?: number
}

/**
 * A fragment shader over a fullscreen triangle.
 *
 * `fragment` defines `vec4 render(vec2 uv)` — plus any helpers it wants —
 * and nothing else. Uniforms, noise and `main()` come from `GLSL_PRELUDE`
 * and `GLSL_EPILOGUE` below, which is how a design stays 30 lines instead
 * of 130 and how fifteen designs agree on what `uv` means.
 *
 * `render` returns straight (non-premultiplied) alpha. The epilogue
 * premultiplies, once, so no design has to remember to.
 */
export interface GLProgram extends ProgramBase {
  kind: 'webgl'
  fragment: string
}

/** One frame's state, handed to a 2D program's `draw`. */
export interface Canvas2DFrame {
  /** CSS pixels — the context is already scaled for device pixel ratio. */
  width: number
  height: number
  /** Seconds since mount, advancing only while the surface is on screen. */
  time: number
  /** Pointer in 0..1 surface space, smoothed; centre when never moved. */
  pointer: { x: number; y: number }
  /** The active palette, theme-resolved, as CSS colour strings. */
  palette: ShaderPalette
  /** True when the dark palette is in use. */
  dark: boolean
}

/**
 * A 2D draw call per frame.
 *
 * Two of the fifteen designs live here, both for the same reason: they draw
 * *things*, not fields. ASCII needs glyphs — a fragment shader can fake
 * them with bit-packed bitmaps, and the result is a shader nobody can edit.
 * Particles need a list that survives between frames. Everything that is
 * genuinely a per-pixel function is a shader.
 */
export interface Canvas2DProgram extends ProgramBase {
  kind: 'canvas'
  /**
   * Per-surface state, created once at mount. Particle positions live here
   * rather than in module scope, so two cards showing the same effect do
   * not share one swarm.
   */
  init?: (frame: Canvas2DFrame) => unknown
  draw: (ctx: CanvasRenderingContext2D, frame: Canvas2DFrame, state: unknown) => void
}

export type ShaderProgram = GLProgram | Canvas2DProgram

/* ------------------------------------------------------------------ *
 *  The GLSL contract
 * ------------------------------------------------------------------ */

/**
 * Everything a design may assume exists, prepended to its `fragment`.
 *
 * Targets GLSL ES 1.00 (WebGL 1) rather than 3.00: WebGL 2 is everywhere
 * that matters now, but a WebGL 1 shader runs on both and the designs use
 * nothing that would benefit from the newer language. Loop bounds are
 * constant throughout for the same reason — ES 1.00 only guarantees
 * constant-expression bounds, and a driver that rejects a dynamic one does
 * it at compile time on somebody else's phone.
 *
 * `highp` is requested and `mediump` accepted: precision qualifiers are not
 * guaranteed in fragment shaders on WebGL 1, and the fallback is the
 * difference between banding and a blank canvas.
 */
export const GLSL_PRELUDE = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2  u_resolution;
uniform float u_time;
uniform vec2  u_pointer;
uniform vec3  u_c0;
uniform vec3  u_c1;
uniform vec3  u_c2;
uniform vec3  u_bg;

const float PI = 3.141592653589793;

mat2 rot(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

/** One of the three palette colours, by index. Avoids arrays in ES 1.00. */
vec3 palette(float i) {
  return i < 0.5 ? u_c0 : (i < 1.5 ? u_c1 : u_c2);
}

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

/** Value noise. Cheaper than gradient noise and indistinguishable under fbm. */
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash21(i), hash21(i + vec2(1.0, 0.0)), u.x),
    mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

/** Five octaves, each rotated so the lattice never shows as a grid. */
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p = rot(0.5) * p * 2.02;
    a *= 0.5;
  }
  return v;
}

/** 0..1 uv to aspect-corrected -1..1, so circles stay circular. */
vec2 aspect(vec2 uv) {
  vec2 p = uv * 2.0 - 1.0;
  p.x *= u_resolution.x / u_resolution.y;
  return p;
}

/** Ordered-dither thresholds, used by more than one design. */
float bayer2(vec2 a) {
  a = floor(a);
  return fract(a.x / 2.0 + a.y * a.y * 0.75);
}
float bayer4(vec2 a) { return bayer2(0.5 * a) * 0.25 + bayer2(a); }
float bayer8(vec2 a) { return bayer4(0.5 * a) * 0.25 + bayer2(a); }
`

/** `main()`, appended after the design's `render`. */
export const GLSL_EPILOGUE = `
void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution;
  vec4 c = render(uv);
  gl_FragColor = vec4(clamp(c.rgb, 0.0, 1.0) * c.a, c.a);
}
`

const VERTEX_SOURCE = `attribute vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`

/* ------------------------------------------------------------------ *
 *  The fallback
 * ------------------------------------------------------------------ */

/**
 * What the surface shows when the shader cannot run.
 *
 * Every shader effect paints this behind its canvas, and a canvas with no
 * context is a transparent rectangle — so a visitor with WebGL disabled, a
 * driver on a blocklist, a browser in a lockdown mode, or simply a slow
 * first paint sees a gradient in the design's own colours rather than a
 * hole in the page.
 *
 * Derived from the palette rather than authored per design, which is the
 * point: a hand-written fallback is a second copy of the design's colours,
 * and it goes stale the first time somebody retunes a palette and does not
 * think about the case they cannot see.
 */
export function fallbackBackground(palette: ShaderPalette): string {
  return `linear-gradient(145deg, ${palette.bg} 0%, ${palette.c0} 58%, ${palette.c1} 100%)`
}

/* ------------------------------------------------------------------ *
 *  Noise, for the 2D programs
 * ------------------------------------------------------------------ */

/**
 * The same value noise the prelude gives shaders, in JavaScript.
 *
 * The two 2D designs need a coherent field just as much as the thirteen
 * shaders do, and they cannot reach into GLSL for it. Kept here rather than
 * copied into each: it is shipped alongside them either way, and two
 * hand-tuned hash constants that drift apart is a bug nobody would find.
 */
export function hash2D(x: number, y: number): number {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453
  return s - Math.floor(s)
}

/** Value noise in 2D, smoothstep-interpolated. Range 0..1. */
export function noise2D(x: number, y: number): number {
  const ix = Math.floor(x)
  const iy = Math.floor(y)
  const fx = x - ix
  const fy = y - iy
  const ux = fx * fx * (3 - 2 * fx)
  const uy = fy * fy * (3 - 2 * fy)

  const a = hash2D(ix, iy)
  const b = hash2D(ix + 1, iy)
  const c = hash2D(ix, iy + 1)
  const d = hash2D(ix + 1, iy + 1)

  return (a + (b - a) * ux) * (1 - uy) + (c + (d - c) * ux) * uy
}

/** Four octaves of `noise2D`. Range 0..1. */
export function fbm2D(x: number, y: number): number {
  let v = 0
  let a = 0.5
  let px = x
  let py = y
  for (let i = 0; i < 4; i++) {
    v += a * noise2D(px, py)
    // Rotate between octaves so the lattice never shows as a grid.
    const nx = px * 1.74 - py * 1.02
    py = px * 1.02 + py * 1.74
    px = nx
    a *= 0.5
  }
  return v
}

/* ------------------------------------------------------------------ *
 *  Mounting
 * ------------------------------------------------------------------ */

export interface MountOptions {
  /** Which palette to use. Flip it with `setTheme`, not by remounting. */
  dark: boolean
  /**
   * Freeze on a single representative frame instead of animating.
   *
   * Not "render nothing": a still aurora is still an aurora, and the
   * visitor who asked for less motion still came to look at the catalog.
   * See `STILL_TIME`.
   */
  reducedMotion?: boolean
  /**
   * Element whose pointer position drives `u_pointer`. Defaults to the
   * canvas; card previews pass the whole card, so the effect answers the
   * pointer anywhere on the tile rather than only over the canvas itself.
   */
  pointerTarget?: HTMLElement | null
  /**
   * Called when the surface cannot run at all — no WebGL, a shader that
   * failed to compile, a context that was lost and never came back. The
   * caller's job is to leave the CSS fallback visible; every shader
   * effect's markup paints one behind the canvas for exactly this.
   */
  onFallback?: (reason: string) => void
}

export interface ShaderHandle {
  setTheme: (dark: boolean) => void
  setReducedMotion: (reduced: boolean) => void
  /** Render one frame now, whatever the run state. Used by the screenshotter. */
  redraw: () => void
  destroy: () => void
}

/**
 * The moment a frozen surface is rendered at.
 *
 * Zero is the wrong choice: most of these designs start from a symmetric or
 * empty state — the metaballs are stacked, the lightning has not struck,
 * the particles are on their seed lattice — and freezing there shows the
 * one frame that does not look like the effect. A few seconds in, every
 * design has settled into what it actually is.
 */
const STILL_TIME = 6.2

/** Device pixel ratio is capped: a 3x aurora is invisible and costs 9x. */
const MAX_DPR = 2

const NOOP_HANDLE: ShaderHandle = {
  setTheme: () => {},
  setReducedMotion: () => {},
  redraw: () => {},
  destroy: () => {},
}

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.trim().replace('#', '')
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2]
  const n = Number.parseInt(h, 16)
  if (!Number.isFinite(n)) return [0, 0, 0]
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]
}

/**
 * Start a program on a canvas. Returns a handle; call `destroy` on unmount.
 *
 * Safe to call with a canvas that is off screen, zero-sized, or in a
 * document that never becomes visible — nothing is drawn until an
 * `IntersectionObserver` says the surface is on screen, and nothing keeps
 * running once it leaves. A 24-card grid of shaders therefore costs the
 * frames of the four cards a visitor can actually see.
 */
export function mountShader(
  canvas: HTMLCanvasElement,
  program: ShaderProgram,
  opts: MountOptions,
): ShaderHandle {
  if (typeof window === 'undefined') return NOOP_HANDLE

  let dark = opts.dark
  let reduced = opts.reducedMotion === true
  let disposed = false

  /* -- Shared frame state ------------------------------------------ */

  let width = 0
  let height = 0
  let dpr = 1
  let time = 0
  let lastFrame = 0
  let raf = 0
  let onScreen = false
  const pointer = { x: 0.5, y: 0.5 }
  const pointerTarget = { x: 0.5, y: 0.5 }
  const speed = program.speed ?? 1

  const fail = (reason: string) => {
    canvas.dataset.shaderState = 'fallback'
    opts.onFallback?.(reason)
    return NOOP_HANDLE
  }

  /**
   * Match the drawing buffer to the element's CSS box.
   *
   * Returns whether anything changed, because for WebGL a resize means a
   * new viewport and for 2D it means the transform has to be re-applied —
   * and on a card that never resizes, both are wasted work every frame.
   */
  const resize = (): boolean => {
    const rect = canvas.getBoundingClientRect()
    const nextDpr = Math.min(window.devicePixelRatio || 1, MAX_DPR)
    const w = Math.max(1, Math.round(rect.width))
    const h = Math.max(1, Math.round(rect.height))
    if (w === width && h === height && nextDpr === dpr) return false
    width = w
    height = h
    dpr = nextDpr
    canvas.width = Math.round(w * dpr)
    canvas.height = Math.round(h * dpr)
    return true
  }

  /* -- Per-kind renderers ------------------------------------------ */

  const renderers = {
    webgl: () => setupGL(canvas, program as GLProgram, fail),
    canvas: () => setupCanvas2D(canvas, program as Canvas2DProgram, fail),
  }
  const backend = renderers[program.kind]()
  if (!backend) return NOOP_HANDLE

  const draw = () => {
    if (disposed) return
    resize()
    if (width === 0 || height === 0) return
    backend.draw({
      width,
      height,
      dpr,
      time,
      pointer,
      palette: dark ? program.dark : program.light,
      dark,
    })
    canvas.dataset.shaderState = 'running'
  }

  /* -- The loop ----------------------------------------------------- */

  const tick = (now: number) => {
    raf = 0
    if (disposed) return
    const dt = lastFrame === 0 ? 0 : Math.min((now - lastFrame) / 1000, 1 / 15)
    lastFrame = now
    time += dt * speed
    if (program.pointer) {
      // Exponential ease rather than a hard set: a pointer that jumps
      // 400px between two frames should drag the effect with it, not
      // teleport it.
      pointer.x += (pointerTarget.x - pointer.x) * 0.12
      pointer.y += (pointerTarget.y - pointer.y) * 0.12
    }
    draw()
    schedule()
  }

  const schedule = () => {
    if (disposed || raf !== 0) return
    if (reduced || !onScreen || document.hidden) return
    raf = window.requestAnimationFrame(tick)
  }

  const stop = () => {
    if (raf !== 0) {
      window.cancelAnimationFrame(raf)
      raf = 0
    }
    lastFrame = 0
  }

  const start = () => {
    if (reduced) {
      // One frame, at a moment that looks like the effect, then nothing.
      time = program.stillTime ?? STILL_TIME
      draw()
      return
    }
    schedule()
  }

  /* -- What starts and stops it ------------------------------------- */

  const io = new IntersectionObserver(
    (entries) => {
      const next = entries.some((e) => e.isIntersecting)
      if (next === onScreen) return
      onScreen = next
      if (onScreen) start()
      else stop()
    },
    { rootMargin: '120px' },
  )
  io.observe(canvas)

  const ro =
    typeof ResizeObserver === 'undefined'
      ? null
      : new ResizeObserver(() => {
          // A resize while frozen still has to repaint: the frame on screen
          // was drawn for a box that no longer exists.
          if (reduced || !onScreen) draw()
        })
  ro?.observe(canvas)

  const onVisibility = () => {
    if (document.hidden) stop()
    else if (onScreen) start()
  }
  document.addEventListener('visibilitychange', onVisibility)

  /* -- Pointer ------------------------------------------------------ */

  const target = opts.pointerTarget ?? canvas
  const onPointerMove = (e: PointerEvent) => {
    const rect = canvas.getBoundingClientRect()
    if (rect.width === 0 || rect.height === 0) return
    pointerTarget.x = (e.clientX - rect.left) / rect.width
    // Flipped: GL's origin is bottom-left, the DOM's is top-left, and a
    // design that reacts to the pointer should react upward when the
    // pointer moves up.
    pointerTarget.y = 1 - (e.clientY - rect.top) / rect.height
  }
  const onPointerLeave = () => {
    pointerTarget.x = 0.5
    pointerTarget.y = 0.5
  }
  if (program.pointer) {
    target.addEventListener('pointermove', onPointerMove)
    target.addEventListener('pointerleave', onPointerLeave)
  }

  /* -- Context loss -------------------------------------------------- */

  const onContextLost = (e: Event) => {
    // Without preventDefault the context is never restored, and the card is
    // blank for the rest of the session.
    e.preventDefault()
    stop()
    canvas.dataset.shaderState = 'lost'
  }
  const onContextRestored = () => {
    if (disposed) return
    if (!backend.restore()) {
      fail('context restore failed')
      return
    }
    width = 0
    height = 0
    if (onScreen) start()
  }
  canvas.addEventListener('webglcontextlost', onContextLost)
  canvas.addEventListener('webglcontextrestored', onContextRestored)

  return {
    setTheme: (nextDark: boolean) => {
      if (nextDark === dark) return
      dark = nextDark
      // Repaint immediately even when frozen or off screen: a theme switch
      // that only lands on the next scroll reads as a broken preview.
      draw()
    },
    setReducedMotion: (nextReduced: boolean) => {
      if (nextReduced === reduced) return
      reduced = nextReduced
      stop()
      if (onScreen) start()
    },
    redraw: draw,
    destroy: () => {
      disposed = true
      stop()
      io.disconnect()
      ro?.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
      if (program.pointer) {
        target.removeEventListener('pointermove', onPointerMove)
        target.removeEventListener('pointerleave', onPointerLeave)
      }
      canvas.removeEventListener('webglcontextlost', onContextLost)
      canvas.removeEventListener('webglcontextrestored', onContextRestored)
      backend.destroy()
    },
  }
}

/* ------------------------------------------------------------------ *
 *  Backends
 * ------------------------------------------------------------------ */

interface DrawState {
  width: number
  height: number
  dpr: number
  time: number
  pointer: { x: number; y: number }
  palette: ShaderPalette
  dark: boolean
}

interface Backend {
  draw: (s: DrawState) => void
  /** Rebuild after a lost context. False means give up and fall back. */
  restore: () => boolean
  destroy: () => void
}

function setupGL(
  canvas: HTMLCanvasElement,
  program: GLProgram,
  fail: (reason: string) => ShaderHandle,
): Backend | null {
  // `alpha: true` with `premultipliedAlpha: true` is what lets a design
  // return alpha < 1 and sit over whatever the page put behind it — the
  // orb and the lightning both do, and compositing them onto an opaque
  // black square would defeat the point of the CSS fallback underneath.
  const attrs: WebGLContextAttributes = {
    alpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: true,
    powerPreference: 'low-power',
    preserveDrawingBuffer: true,
  }

  const gl =
    (canvas.getContext('webgl', attrs) as WebGLRenderingContext | null) ??
    (canvas.getContext('experimental-webgl', attrs) as WebGLRenderingContext | null)

  if (!gl) {
    fail('no webgl context')
    return null
  }

  let glProgram: WebGLProgram | null = null
  let buffer: WebGLBuffer | null = null
  let uniforms: Record<string, WebGLUniformLocation | null> = {}
  let lastW = -1
  let lastH = -1

  const compile = (type: number, source: string): WebGLShader | null => {
    const shader = gl.createShader(type)
    if (!shader) return null
    gl.shaderSource(shader, source)
    gl.compileShader(shader)
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      // Kept as a warning rather than a throw: one design failing to
      // compile on one driver should cost that card its animation, not the
      // page its render.
      console.warn(
        `[hoverlab] shader "${program.id}" failed to compile:\n${gl.getShaderInfoLog(shader)}`,
      )
      gl.deleteShader(shader)
      return null
    }
    return shader
  }

  const build = (): boolean => {
    const vs = compile(gl.VERTEX_SHADER, VERTEX_SOURCE)
    const fs = compile(
      gl.FRAGMENT_SHADER,
      GLSL_PRELUDE + program.fragment + GLSL_EPILOGUE,
    )
    if (!vs || !fs) return false

    const p = gl.createProgram()
    if (!p) return false
    gl.attachShader(p, vs)
    gl.attachShader(p, fs)
    gl.linkProgram(p)
    // The shader objects are referenced by the program now; keeping them
    // alive leaks one pair per card in a grid that scrolls.
    gl.deleteShader(vs)
    gl.deleteShader(fs)
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
      console.warn(`[hoverlab] shader "${program.id}" failed to link:\n${gl.getProgramInfoLog(p)}`)
      gl.deleteProgram(p)
      return false
    }

    glProgram = p
    gl.useProgram(p)

    // A fullscreen *triangle*, not a quad: two triangles meeting on the
    // diagonal make the GPU shade that seam twice, and one oversized
    // triangle clipped to the viewport covers the same pixels once.
    buffer = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 3, -1, -1, 3]),
      gl.STATIC_DRAW,
    )
    const loc = gl.getAttribLocation(p, 'a_pos')
    gl.enableVertexAttribArray(loc)
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0)

    uniforms = {}
    for (const name of ['u_resolution', 'u_time', 'u_pointer', 'u_c0', 'u_c1', 'u_c2', 'u_bg']) {
      uniforms[name] = gl.getUniformLocation(p, name)
    }
    lastW = -1
    lastH = -1
    return true
  }

  if (!build()) {
    fail('shader build failed')
    return null
  }

  return {
    draw: (s) => {
      if (!glProgram || gl.isContextLost()) return
      const w = canvas.width
      const h = canvas.height
      if (w !== lastW || h !== lastH) {
        gl.viewport(0, 0, w, h)
        lastW = w
        lastH = h
      }
      gl.useProgram(glProgram)
      gl.uniform2f(uniforms.u_resolution, w, h)
      gl.uniform1f(uniforms.u_time, s.time)
      gl.uniform2f(uniforms.u_pointer, s.pointer.x, s.pointer.y)
      const c0 = hexToRgb(s.palette.c0)
      const c1 = hexToRgb(s.palette.c1)
      const c2 = hexToRgb(s.palette.c2)
      const bg = hexToRgb(s.palette.bg)
      gl.uniform3f(uniforms.u_c0, c0[0], c0[1], c0[2])
      gl.uniform3f(uniforms.u_c1, c1[0], c1[1], c1[2])
      gl.uniform3f(uniforms.u_c2, c2[0], c2[1], c2[2])
      gl.uniform3f(uniforms.u_bg, bg[0], bg[1], bg[2])
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    },
    restore: build,
    destroy: () => {
      if (gl.isContextLost()) return
      if (buffer) gl.deleteBuffer(buffer)
      if (glProgram) gl.deleteProgram(glProgram)
      // Frees the drawing buffer now rather than whenever the GC gets to
      // it. Browsers cap live contexts at ~16; a catalog grid scrolled for
      // a minute will hit that.
      gl.getExtension('WEBGL_lose_context')?.loseContext()
    },
  }
}

function setupCanvas2D(
  canvas: HTMLCanvasElement,
  program: Canvas2DProgram,
  fail: (reason: string) => ShaderHandle,
): Backend | null {
  const ctx = canvas.getContext('2d')
  if (!ctx) {
    fail('no 2d context')
    return null
  }

  let state: unknown = null
  let seededFor = ''

  return {
    draw: (s) => {
      const frame: Canvas2DFrame = {
        width: s.width,
        height: s.height,
        time: s.time,
        pointer: s.pointer,
        palette: s.palette,
        dark: s.dark,
      }
      // Re-seed on a real resize, not on every frame: a particle field laid
      // out for a 320px card is wrong at 900px, and re-seeding every frame
      // is a field that never moves.
      const key = `${s.width}x${s.height}`
      if (key !== seededFor) {
        state = program.init ? program.init(frame) : null
        seededFor = key
      }
      ctx.setTransform(s.dpr, 0, 0, s.dpr, 0, 0)
      /*
       * The backend paints the palette's background before the program
       * draws, rather than clearing to transparent.
       *
       * A fragment shader covers every pixel it is given, so a WebGL design
       * is opaque by construction. A 2D program draws a few hundred glyphs
       * or dots and leaves the rest alone — so clearing left both 2D
       * designs showing whatever was behind the canvas, which is the CSS
       * *fallback* gradient. A fallback that is load-bearing for two of the
       * fifteen is not a fallback, and the two designs looked wrong in
       * light mode for exactly that reason: their background was a gradient
       * tuned to stand in for them, not to sit under them.
       */
      ctx.fillStyle = s.palette.bg
      ctx.fillRect(0, 0, s.width, s.height)
      program.draw(ctx, frame, state)
    },
    restore: () => true,
    destroy: () => {
      state = null
    },
  }
}

'use client'

/**
 * The React surface a shader is drawn on.
 *
 * Thin on purpose: it owns a canvas, a ref and three effects, and every
 * decision about *what* to draw is in `./runtime`. That split is what lets
 * the catalog's DOM scanner and a buyer's React tree run the same code.
 *
 * SHIPPED FILE. One of the three a buyer copies, so it imports nothing but
 * React and the runtime, and it reads the theme off the DOM rather than
 * from a provider — `next-themes`, `class-variance-authority` and a
 * hand-rolled context all end up setting `class="dark"` on <html>, and that
 * is the one thing they agree on.
 */

import * as React from 'react'

import {
  fallbackBackground,
  mountShader,
  type ShaderHandle,
  type ShaderProgram,
} from './shader-runtime'

export interface ShaderSurfaceProps {
  program: ShaderProgram
  /**
   * Force a palette instead of following the document's theme. Useful for a
   * section that is dark whatever the page around it is doing.
   */
  dark?: boolean
  className?: string
  style?: React.CSSProperties
  /**
   * Content drawn over the shader. Positioned by the caller; the surface
   * only guarantees it sits above the canvas and takes pointer events.
   */
  children?: React.ReactNode
}

/** True when the document is in dark mode, by the convention every setup shares. */
function readDocumentDark(): boolean {
  if (typeof document === 'undefined') return false
  return document.documentElement.classList.contains('dark')
}

/**
 * Follow the document's theme class.
 *
 * A `MutationObserver` rather than a media query: the site has a manual
 * toggle, so the OS preference is not the answer — what the toggle writes
 * is. Returns `override` unchanged when the caller pinned a palette.
 */
function useDocumentDark(override?: boolean): boolean {
  const [dark, setDark] = React.useState(false)

  React.useEffect(() => {
    if (override !== undefined) return
    const sync = () => setDark(readDocumentDark())
    sync()
    const mo = new MutationObserver(sync)
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
    })
    return () => mo.disconnect()
  }, [override])

  return override ?? dark
}

/** Follow `prefers-reduced-motion`. */
function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState(false)

  React.useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const sync = () => setReduced(mq.matches)
    sync()
    mq.addEventListener('change', sync)
    return () => mq.removeEventListener('change', sync)
  }, [])

  return reduced
}

export function ShaderSurface({
  program,
  dark: darkOverride,
  className,
  style,
  children,
}: ShaderSurfaceProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const hostRef = React.useRef<HTMLDivElement>(null)
  const handleRef = React.useRef<ShaderHandle | null>(null)

  const dark = useDocumentDark(darkOverride)
  const reduced = usePrefersReducedMotion()

  /*
   * Mount once per program. Theme and reduced-motion go through the handle
   * rather than the dependency list: both change while the visitor is
   * looking at the surface, and remounting would recompile the shader and
   * restart time from zero — a theme toggle that makes the aurora jump.
   */
  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const handle = mountShader(canvas, program, {
      dark: readDocumentDark(),
      reducedMotion: window.matchMedia('(prefers-reduced-motion: reduce)').matches,
      // The pointer follows the whole surface, not just the canvas, so
      // content laid over the shader does not cut a hole in the tracking.
      pointerTarget: hostRef.current,
    })
    handleRef.current = handle
    return () => {
      handle.destroy()
      handleRef.current = null
    }
  }, [program])

  React.useEffect(() => {
    handleRef.current?.setTheme(dark)
  }, [dark])

  React.useEffect(() => {
    handleRef.current?.setReducedMotion(reduced)
  }, [reduced])

  const palette = dark ? program.dark : program.light

  return (
    <div
      ref={hostRef}
      className={className}
      style={{ position: 'relative', isolation: 'isolate', ...style }}
    >
      <canvas
        ref={canvasRef}
        /*
         * The fallback is on the canvas itself rather than on a sibling: a
         * canvas with no context — no WebGL, a driver that refused the
         * shader, a browser that blocked it — is a transparent rectangle,
         * and it still has its own background behind it. Nothing to
         * coordinate, nothing to hide on success.
         */
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          display: 'block',
          background: fallbackBackground(palette),
        }}
        // Decoration. The content over it is what anybody reads.
        aria-hidden="true"
      />
      {children != null && <div style={{ position: 'relative' }}>{children}</div>}
    </div>
  )
}

aurora-veil.source:
'use client'

/**
 * Aurora Veil — three drifting ribbons of light over a night sky.
 *
 * The thing that separates an aurora from a blurred gradient is the
 * vertical striation: real curtains are made of parallel strands that
 * brighten and fade independently along their length. A CSS gradient can
 * blur two colours together and it will never do that, which is why this
 * is the first design in the shader tier rather than the hundredth.
 *
 * Each ribbon is a horizontal line whose height wanders with fbm, glowed
 * with a gaussian falloff and then multiplied by a second, much finer noise
 * running across it. Three ribbons, one per palette colour, each on its own
 * clock so they drift apart instead of moving as a block.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const AURORA_VEIL_PROGRAM: GLProgram = {
  id: 'aurora-veil',
  kind: 'webgl',
  speed: 1,
  /*
   * The light palette is saturated where the dark one is bright. Both
   * versions of this design paint the same shapes; what changes is whether
   * a ribbon is lighter or darker than what it is on, and a pastel teal on
   * a near-white sky is neither.
   */
  light: { c0: '#0d9488', c1: '#4f46e5', c2: '#c026d3', bg: '#f4f6ff' },
  dark: { c0: '#34d399', c1: '#6366f1', c2: '#e879f9', bg: '#05060f' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time * 0.14;
  vec3 col = u_bg;

  for (int i = 0; i < 3; i++) {
    float fi = float(i);

    // The ribbon's centre line: a slow, large-scale wander. The x term is
    // scaled down hard so the curtain bends across the whole width rather
    // than wobbling within it.
    float centre = 0.42 + fi * 0.16
      + 0.30 * (fbm(vec2(p.x * 0.80 + t * (0.7 + fi * 0.22) + fi * 7.0, t * 0.4)) - 0.5);

    float d = uv.y - centre;

    // Sharp along the top edge and trailing away underneath, because a
    // curtain hangs. A symmetric falloff — which is what this was — gives a
    // horizontal bar of light, and three of them read as an equaliser.
    float glow = d > 0.0 ? exp(-d * d * 150.0) : exp(-d * d * (26.0 + fi * 6.0));

    /*
     * The strands, and the reason this is not a gradient. High frequency
     * across, almost none along: noise sampled that way stretches into
     * vertical filaments rather than resolving into blobs. Two octaves, the
     * second four times finer, so the curtain has structure at the scale
     * you notice and at the scale you only feel.
     */
    float strands =
      0.30 + 0.70 * vnoise(vec2(p.x * 13.0 + t * 2.6 + fi * 5.0, uv.y * 0.8 + fi * 3.0));
    strands *= 0.55 + 0.45 * vnoise(vec2(p.x * 31.0 - t * 1.4, fi * 2.0));

    /*
     * Blended toward the ribbon's colour, not added to it.
     *
     * Adding is what an aurora physically does — it is emitted light — and
     * it is correct on a night sky and useless on a white one, because a
     * near-white background is already at the top of the range and has
     * nowhere to go. Mixing paints the same shapes in either direction:
     * lighter than a dark sky, darker than a pale one. Measured on the
     * render harness, this is the difference between a luminance spread of
     * 9 and one of 130 in the light palette.
     */
    col = mix(col, palette(fi), clamp(glow * strands * (1.0 - fi * 0.12), 0.0, 1.0));
  }

  // A wash at the horizon so the ribbons sit in something rather than
  // floating on a flat field.
  col = mix(col, u_c2, 0.06 * smoothstep(0.85, 0.0, uv.y));

  return vec4(col, 1.0);
}
`,
}

export function AuroraVeil({ className }: { className?: string }) {
  return <ShaderSurface program={AURORA_VEIL_PROGRAM} className={className} />
}

plasma-field.source:
'use client'

/**
 * Plasma Field — four interfering sine waves, coloured by the interference.
 *
 * The oldest demoscene effect there is, and still the cheapest way to fill a
 * hero with something that is unmistakably computed rather than drawn: four
 * sines (two axis-aligned, one diagonal, one radial), summed, then used as
 * the phase of two more. No noise, no texture lookups, no loop — the whole
 * thing is about fifteen instructions and it runs at full rate on a phone.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const PLASMA_FIELD_PROGRAM: GLProgram = {
  id: 'plasma-field',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#a5b4fc', c1: '#fda4af', c2: '#fef08a', bg: '#f8fafc' },
  dark: { c0: '#4338ca', c1: '#be123c', c2: '#fbbf24', bg: '#0b0714' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv) * 1.7;
  float t = u_time * 0.45;

  float v = sin(p.x * 2.0 + t);
  v += sin(p.y * 2.3 - t * 0.8);
  v += sin((p.x + p.y) * 1.7 + t * 0.6);
  v += sin(length(p * 1.35) * 3.0 - t * 1.3);
  v *= 0.25;

  // Two readings of the same field at different frequencies. Using one
  // would give smooth bands; two beating against each other is what makes
  // the cell structure appear and dissolve.
  float a = 0.5 + 0.5 * sin(v * PI * 1.5);
  float b = 0.5 + 0.5 * cos(v * PI * 2.5 + 1.2);

  vec3 col = mix(u_bg, u_c0, a);
  col = mix(col, u_c1, b * 0.65);

  // The accent only appears where both readings peak, which is a small
  // fraction of the surface — an accent everywhere is not an accent.
  col += u_c2 * pow(a * b, 3.0) * 1.1;

  return vec4(col, 1.0);
}
`,
}

export function PlasmaField({ className }: { className?: string }) {
  return <ShaderSurface program={PLASMA_FIELD_PROGRAM} className={className} />
}

liquid-metal.source:
'use client'

/**
 * Liquid Metal — domain-warped noise, banded like a polished surface.
 *
 * Three nested fbm lookups: the field is sampled at a position that is
 * itself the output of a field, twice. That is the standard way to get
 * folds and eddies out of noise that would otherwise look like fog, and it
 * is the reason this reads as a fluid with a surface rather than a cloud.
 *
 * The metal comes from the banding. `fract(f * 5)` cuts the smooth field
 * into contours, and a narrow smoothstep across each contour's leading edge
 * is a specular highlight — polished metal is exactly a surface where small
 * changes in angle make large changes in what you see.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const LIQUID_METAL_PROGRAM: GLProgram = {
  id: 'liquid-metal',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#94a3b8', c1: '#c4b5fd', c2: '#ffffff', bg: '#e2e8f0' },
  dark: { c0: '#1e293b', c1: '#7c3aed', c2: '#e2e8f0', bg: '#020617' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv) * 1.25;
  float t = u_time * 0.11;

  vec2 q = vec2(fbm(p + vec2(0.0, t)), fbm(p + vec2(5.2, 1.3 - t)));
  vec2 r = vec2(
    fbm(p + 3.0 * q + vec2(1.7, 9.2) + t * 0.5),
    fbm(p + 3.0 * q + vec2(8.3, 2.8) - t * 0.4)
  );
  float f = fbm(p + 3.5 * r);

  // Contour lines through the field. The asymmetric smoothstep pair is a
  // hard leading edge and a soft trailing one, which is what a highlight
  // rolling over a curved surface looks like.
  float bands = fract(f * 5.0);
  float sheen = smoothstep(0.0, 0.07, bands) * smoothstep(0.52, 0.26, bands);

  vec3 col = mix(u_bg, u_c0, clamp(f * 1.5, 0.0, 1.0));
  col = mix(col, u_c1, clamp(length(r) * 0.85, 0.0, 1.0));
  col += u_c2 * sheen * 0.8;

  return vec4(col, 1.0);
}
`,
}

export function LiquidMetal({ className }: { className?: string }) {
  return <ShaderSurface program={LIQUID_METAL_PROGRAM} className={className} />
}

iridescence.source:
'use client'

/**
 * Iridescence — thin-film interference, which is why the colours cycle.
 *
 * A soap bubble is not coloured. What you see is the film's thickness
 * deciding which wavelengths cancel and which reinforce, so the hue is a
 * function of the *phase*, and the three channels are the same function
 * offset by a third of a turn. That is the entire model here: one phase,
 * three cosines at 120° apart, each weighting a palette colour.
 *
 * Because the three colours are sampled from one continuous phase, the
 * result sweeps through the palette rather than crossfading between two
 * ends of it — a gradient cannot do that, and it is the difference between
 * "oil slick" and "purple to pink".
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const IRIDESCENCE_PROGRAM: GLProgram = {
  id: 'iridescence',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#38bdf8', c1: '#f472b6', c2: '#facc15', bg: '#f8fafc' },
  dark: { c0: '#0ea5e9', c1: '#db2777', c2: '#a3e635', bg: '#07050d' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time * 0.18;

  // Stand-in for the film's thickness: a warped field, so the bands bend
  // and pool the way a real film does over an uneven surface.
  vec2 w = vec2(fbm(p * 1.35 + vec2(t, 0.0)), fbm(p * 1.35 + vec2(0.0, t * 0.8)));
  float phase = 6.5 * (w.x - w.y) + length(p) * 2.1 + t * 0.7;

  float a = 0.5 + 0.5 * cos(phase);
  float b = 0.5 + 0.5 * cos(phase + 2.0944);
  float c = 0.5 + 0.5 * cos(phase + 4.1888);

  vec3 col = u_c0 * a + u_c1 * b + u_c2 * c;
  col = mix(u_bg, col, 0.88);

  // A slow grain over the top. Without it the bands are too clean and the
  // surface reads as plastic rather than as a film on something.
  col *= 0.78 + 0.32 * fbm(p * 2.6 - t);

  return vec4(col, 1.0);
}
`,
}

export function Iridescence({ className }: { className?: string }) {
  return <ShaderSurface program={IRIDESCENCE_PROGRAM} className={className} />
}

dither-gradient.source:
'use client'

/**
 * Dither Gradient — a two-tone gradient, resolved by an 8×8 ordered matrix.
 *
 * A gradient is the one thing CSS does perfectly, so this is deliberately
 * the opposite of one: the field is quantised to two or three tones and the
 * in-between values are carried by a Bayer threshold pattern instead of by
 * colour. What you get is the 1-bit look — Playdate, old Mac, Obra Dinn —
 * which cannot be approximated by `background-image` at any size, because
 * the pattern has to be evaluated per pixel against a moving field.
 *
 * The dither grid is expressed against `u_resolution`, not `gl_FragCoord`.
 * Threshold patterns are usually written in device pixels, and on a 2x
 * screen that halves the apparent cell size — a dither that disappears on
 * the machines designers own is not a dither.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const DITHER_GRADIENT_PROGRAM: GLProgram = {
  id: 'dither-gradient',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#334155', c1: '#0f172a', c2: '#64748b', bg: '#f1f5f9' },
  dark: { c0: '#a3e635', c1: '#ecfccb', c2: '#365314', bg: '#0a0f07' },
  fragment: `
vec4 render(vec2 uv) {
  // 140 dither cells across the short axis, whatever the device pixel
  // ratio is. Aspect-corrected so the cells stay square.
  vec2 cell = floor(uv * vec2(u_resolution.x / u_resolution.y, 1.0) * 140.0);

  vec2 p = aspect(uv);
  float t = u_time * 0.09;

  /*
   * The field being dithered: a vertical ramp with slow noise on top, so
   * the boundary between tones creeps rather than sitting still. The ramp
   * has to dominate — weighted evenly with the noise, as it was, the tone
   * boundaries wander far enough that the result reads as static rather
   * than as a dithered gradient.
   */
  float field = 0.95 * (1.0 - uv.y) + 0.38 * fbm(p * 1.5 + vec2(t, t * 0.6));

  float threshold = bayer8(cell);
  float lit = step(threshold, field);
  float hot = step(threshold + 0.34, field);

  vec3 col = mix(u_bg, u_c2, lit);
  col = mix(col, u_c0, hot);
  col = mix(col, u_c1, step(threshold + 0.62, field));

  return vec4(col, 1.0);
}
`,
}

export function DitherGradient({ className }: { className?: string }) {
  return <ShaderSurface program={DITHER_GRADIENT_PROGRAM} className={className} />
}

halftone-wave.source:
'use client'

/**
 * Halftone Wave — a rotated dot screen whose dots size with a moving field.
 *
 * Print halftones are set at 15°, 45° or 75° because a screen aligned to
 * the page shows its own grid and fights the image. The same is true here:
 * at 0° this reads as a table of dots, and at 23° it reads as tone. That
 * rotation is one `rot()` call and it is the difference between the effect
 * working and not.
 *
 * Dot radius follows a sine lattice blended with fbm — regular enough to
 * read as a screen, irregular enough not to strobe when it moves.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const HALFTONE_WAVE_PROGRAM: GLProgram = {
  id: 'halftone-wave',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#0f172a', c1: '#e11d48', c2: '#2563eb', bg: '#fffbeb' },
  dark: { c0: '#f8fafc', c1: '#f43f5e', c2: '#38bdf8', bg: '#0c0a09' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time * 0.32;

  float field = 0.5 + 0.5 * sin(p.x * 3.0 + t) * cos(p.y * 2.6 - t * 0.7);
  field = mix(field, fbm(p * 1.6 + t * 0.25), 0.45);

  // 28 cells across the short axis, rotated to the print angle. Expressed
  // in uv rather than gl_FragCoord so the screen keeps its size on a
  // retina display.
  vec2 g = rot(0.4) * (uv * vec2(u_resolution.x / u_resolution.y, 1.0)) * 28.0;
  vec2 c = fract(g) - 0.5;
  float d = length(c);

  float r = 0.54 * field;
  float dotMask = smoothstep(r, r - 0.09, d);

  vec3 ink = mix(u_c0, u_c1, field);
  vec3 col = mix(u_bg, ink, dotMask);

  // The accent rides only the largest dots, so the second colour arrives
  // as the wave crests rather than tinting the whole screen.
  col = mix(col, u_c2, dotMask * pow(field, 5.0));

  return vec4(col, 1.0);
}
`,
}

export function HalftoneWave({ className }: { className?: string }) {
  return <ShaderSurface program={HALFTONE_WAVE_PROGRAM} className={className} />
}

metaball-lava.source:
'use client'

/**
 * Metaball Lava — six inverse-square fields, thresholded into one body.
 *
 * Blobs that merge and separate are the canonical demonstration of an
 * implicit surface: nothing here knows about a shape, only about a scalar
 * field that six points contribute to, and the shape is wherever that field
 * crosses 1. Two blobs touching produce the neck that makes the effect
 * recognisable, and no amount of `border-radius` will ever produce a neck.
 *
 * The rim is the field's crossing band rather than an outline of the shape,
 * which is why it thickens where two blobs are about to meet — exactly
 * where the eye is already looking.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const METABALL_LAVA_PROGRAM: GLProgram = {
  id: 'metaball-lava',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#fb923c', c1: '#f43f5e', c2: '#fde68a', bg: '#fff7ed' },
  dark: { c0: '#ea580c', c1: '#9f1239', c2: '#fcd34d', bg: '#120508' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time * 0.32;

  float f = 0.0;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    // Two incommensurate frequencies per ball, so the set never returns to
    // a formation it has already been in.
    vec2 c = vec2(
      cos(t * (0.50 + fi * 0.13) + fi * 2.1) * (0.62 + 0.18 * hash11(fi)),
      sin(t * (0.43 + fi * 0.11) + fi * 1.3) * 0.58
    );
    float r = 0.19 + 0.11 * hash11(fi + 9.0);
    vec2 d = p - c;
    f += r * r / max(dot(d, d), 1e-4);
  }

  float body = smoothstep(0.92, 1.30, f);
  float rim = smoothstep(0.88, 1.02, f) - smoothstep(1.10, 1.75, f);

  vec3 col = mix(u_bg, mix(u_c0, u_c1, clamp(f * 0.30, 0.0, 1.0)), body);
  col += u_c2 * rim * 0.95;

  return vec4(col, 1.0);
}
`,
}

export function MetaballLava({ className }: { className?: string }) {
  return <ShaderSurface program={METABALL_LAVA_PROGRAM} className={className} />
}

ferrofluid.source:
'use client'

/**
 * Ferrofluid — a metaball field with spikes, which is the whole difference.
 *
 * Ferrofluid is famous for one thing: under a magnetic field it grows
 * regular spikes along the field lines, because the fluid climbs the field
 * faster than surface tension can flatten it. So each blob's radius is
 * modulated by `sin(angle * 9)` rather than being constant, and the
 * modulation is faded out near the blob's centre — spikes belong on the
 * surface, and a blob whose middle also spikes looks like a gear.
 *
 * Dark by default and dark by nature. The material is black; what you are
 * looking at is entirely specular, so the palette's accent does most of the
 * work and the body colour barely appears.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const FERROFLUID_PROGRAM: GLProgram = {
  id: 'ferrofluid',
  kind: 'webgl',
  speed: 1,
  light: { c0: '#1e293b', c1: '#475569', c2: '#22d3ee', bg: '#e2e8f0' },
  dark: { c0: '#020617', c1: '#1e1b4b', c2: '#22d3ee', bg: '#060910' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time * 0.24;

  float f = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    vec2 c = vec2(
      cos(t * (0.60 + fi * 0.20) + fi * 2.4),
      sin(t * (0.50 + fi * 0.17) + fi * 1.1)
    ) * 0.42;

    vec2 d = p - c;
    float ang = atan(d.y, d.x);

    // The spikes. Faded in with distance from the blob's centre so they
    // deform the surface and leave the core round.
    float spike = 1.0 + 0.30 * sin(ang * 9.0 + t * 3.0 + fi * 2.0)
                       * smoothstep(0.0, 0.45, length(d));

    float r = (0.25 + fi * 0.02) * spike;
    f += r * r / max(dot(d, d), 1e-4);
  }

  float body = smoothstep(0.95, 1.22, f);
  float rim = smoothstep(0.93, 1.06, f) - smoothstep(1.20, 2.00, f);
  float sheen = pow(clamp(f - 1.0, 0.0, 2.0), 2.0);

  vec3 col = mix(u_bg, u_c0, body);
  col = mix(col, u_c1, body * clamp(sheen * 0.32, 0.0, 1.0));
  col += u_c2 * rim * 1.15;

  return vec4(col, 1.0);
}
`,
}

export function Ferrofluid({ className }: { className?: string }) {
  return <ShaderSurface program={FERROFLUID_PROGRAM} className={className} />
}

lightning-arc.source:
'use client'

/**
 * Lightning Arc — three filaments that strike on their own clocks.
 *
 * The strike is the design. A bolt that is always there is a squiggle; what
 * makes lightning read as lightning is that most of the time there is
 * nothing, and then there is everything for a tenth of a second. So each
 * filament has a discrete phase — `floor(t)` — and a hash on that phase
 * decides whether this cycle strikes at all. Roughly half do.
 *
 * The bolt itself is a vertical line whose x wanders with fbm, drawn twice:
 * a very tight exponential for the core and a wide one for the glow. Two
 * falloffs rather than one is what gives the corona around the filament
 * without blurring the filament itself.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const LIGHTNING_ARC_PROGRAM: GLProgram = {
  id: 'lightning-arc',
  kind: 'webgl',
  speed: 1,
  /*
   * The bolt is dark against a pale sky and white against a black one. A
   * white bolt on a light background is the same failure the aurora had:
   * the brightest thing on screen is already the background.
   */
  light: { c0: '#4338ca', c1: '#a5b4fc', c2: '#1e1b4b', bg: '#eef2ff' },
  dark: { c0: '#6366f1', c1: '#a78bfa', c2: '#f0f9ff', bg: '#04040a' },
  fragment: `
/** Distance from p to a filament that wanders in x as it climbs. */
float filament(vec2 p, float seed, float t) {
  float x = 0.42 * (fbm(vec2(p.y * 1.5 + seed * 11.0, t * 0.5 + seed)) - 0.5) * 2.0;
  return abs(p.x - x);
}

vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time;
  float total = 0.0;

  for (int i = 0; i < 3; i++) {
    float fi = float(i);

    // One strike cycle per filament, offset so they do not fire together.
    float phase = floor(t * 0.85 + fi * 3.3);
    float life = fract(t * 0.85 + fi * 3.3);

    // Not every cycle strikes, and the ones that do decay fast.
    float strikes = step(0.45, hash11(phase * 1.7 + fi * 17.0));
    float flash = strikes * exp(-life * 7.0);

    vec2 q = p;
    q.x -= (hash11(phase + fi * 5.0) - 0.5) * 1.5;

    /*
     * Two falloffs: a very tight one for the core and a wide one for the
     * corona. One would give either a hard line with no atmosphere or a
     * smudge with no filament.
     *
     * The corona carries more weight than a photograph of lightning would
     * justify, because coverage is what makes a bolt visible against a pale
     * sky — a one-pixel dark line on near-white is a hair, not a strike.
     */
    float d = filament(q, phase + fi, t);
    total += (exp(-d * 170.0) * 1.35 + exp(-d * 9.0) * 0.48) * flash;
  }

  total = clamp(total, 0.0, 1.6);
  float amt = clamp(total, 0.0, 1.0);

  // Mixed, not added, for the reason the aurora is: on a pale sky there is
  // no headroom above the background to add light into.
  vec3 col = mix(u_bg, mix(u_c0, u_c2, amt), amt);
  col = mix(col, u_c1, amt * 0.22);

  return vec4(col, 1.0);
}
`,
}

export function LightningArc({ className }: { className?: string }) {
  return <ShaderSurface program={LIGHTNING_ARC_PROGRAM} className={className} />
}

hyperspeed.source:
'use client'

/**
 * Hyperspeed — radial streaks accelerating out of a vanishing point.
 *
 * Everything is done in polar coordinates, which is what makes it cheap:
 * the angle decides which streak a pixel belongs to, and the radius decides
 * where along that streak it is. No geometry, no particles, no list — 180
 * streaks in three rings cost the same as one.
 *
 * Each streak is brightest at its head and fades back along its tail, which
 * is the read: a line of even brightness moving outward looks like a
 * spoke, and a line that is hot at the front looks like speed.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const HYPERSPEED_PROGRAM: GLProgram = {
  id: 'hyperspeed',
  kind: 'webgl',
  speed: 1,
  /*
   * Streaks are darker than the sky in the light palette and brighter than
   * it in the dark one — see the note on `mix` below. A pale streak on a
   * pale sky is a blank card.
   */
  light: { c0: '#0369a1', c1: '#7dd3fc', c2: '#0f172a', bg: '#f0f9ff' },
  dark: { c0: '#38bdf8', c1: '#a855f7', c2: '#f8fafc', bg: '#01030c' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  float t = u_time * 0.55;

  float a = atan(p.y, p.x) / (2.0 * PI) + 0.5;   // 0..1 around the circle
  float r = length(p);

  float acc = 0.0;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float lanes = 60.0 + fi * 34.0;

    float s = a * lanes + fi * 7.0;
    float id = floor(s);
    float rnd = hash11(id * 1.37 + fi * 3.0);

    // The head travels outward and wraps; each lane has its own speed, so
    // the field never organises itself into a rotating wheel.
    float head = fract(rnd + t * (0.35 + rnd * 0.95));
    float len = 0.10 + rnd * 0.24;

    float band = smoothstep(head - len, head, r) * (1.0 - smoothstep(head, head + 0.02, r));

    // Thin the streak across its lane so it is a line, not a wedge.
    float across = abs(fract(s) - 0.5);
    band *= smoothstep(0.45, 0.04, across);

    acc += band * (0.35 + rnd * 0.75);
  }

  // Nothing resolves at the vanishing point — streaks converge there, and
  // drawing them into it turns the centre into a smear.
  acc *= smoothstep(0.04, 0.34, r);

  /*
   * Blended toward the streak colour rather than added to the sky. Adding
   * is the right model for light and the wrong one for a palette whose
   * background is already near white — there, every streak clips to the
   * same colour as the sky it is crossing.
   */
  float amt = clamp(acc, 0.0, 1.0);
  vec3 col = mix(u_bg, mix(u_c0, u_c2, amt), amt);
  col = mix(col, u_c1, pow(max(0.0, 1.0 - r * 1.7), 4.0) * 0.55);

  return vec4(col, 1.0);
}
`,
}

export function Hyperspeed({ className }: { className?: string }) {
  return <ShaderSurface program={HYPERSPEED_PROGRAM} className={className} />
}

plasma-orb.source:
'use client'

/**
 * Plasma Orb — a sphere with a turbulent surface, a rim and a halo.
 *
 * Two things make a flat disc read as a ball. The first is that the surface
 * noise is sampled in a fake spherical parameterisation — `z` reconstructed
 * from the radius, so the pattern compresses toward the edge the way a
 * texture on a sphere does. The second is the fresnel term: real spheres
 * are brightest where you are looking along their surface, and `pow(1 - z,
 * 3)` is that, cheaply.
 *
 * This is the one design that returns alpha. The body is opaque, the halo
 * fades out, and beyond it the shader writes nothing — so the halo blends
 * into whatever the surface is painted with instead of fading toward a
 * colour the shader had to guess. Drop the surface's own background and the
 * orb will sit on the page behind it; that is what the runtime's
 * premultiplied context is for.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const PLASMA_ORB_PROGRAM: GLProgram = {
  id: 'plasma-orb',
  kind: 'webgl',
  speed: 1,
  pointer: true,
  light: { c0: '#8b5cf6', c1: '#22d3ee', c2: '#f0abfc', bg: '#f5f3ff' },
  dark: { c0: '#7c3aed', c1: '#06b6d4', c2: '#e879f9', bg: '#07040f' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);

  // The orb leans toward the pointer rather than following it — a ball
  // that tracks exactly reads as a cursor, not as an object.
  p -= (u_pointer - 0.5) * 0.22;

  float r = length(p);
  float R = 0.58;
  float t = u_time * 0.28;

  // Reconstructed depth, so the surface noise foreshortens at the limb.
  float z = sqrt(max(0.0, R * R - r * r));
  vec3 n = vec3(p, z) / R;

  float surf = fbm(n.xy * 2.6 + vec2(t, -t * 0.7) + n.z * 0.9);
  float band = 0.5 + 0.5 * sin(surf * 6.5 + t * 2.2);

  float inside = smoothstep(R, R - 0.015, r);
  float fres = pow(1.0 - clamp(z / R, 0.0, 1.0), 3.0);
  float halo = exp(-(r - R) * 6.5) * step(R, r);

  vec3 body = mix(u_c0, u_c1, band) + u_c2 * fres * 1.15;
  vec3 col = mix(u_c2, body, inside);

  // Straight (not premultiplied) alpha — the epilogue premultiplies once,
  // for every design, so none of them have to remember to.
  float alpha = clamp(inside + halo * 0.65, 0.0, 1.0);

  return vec4(col, alpha);
}
`,
}

export function PlasmaOrb({ className }: { className?: string }) {
  return <ShaderSurface program={PLASMA_ORB_PROGRAM} className={className} />
}

grid-distortion.source:
'use client'

/**
 * Grid Distortion — a ruled grid that bends toward the pointer.
 *
 * The grid is not moved; the *space* is. Every pixel resolves its own
 * position, pulls it toward the pointer by a gaussian falloff, and then
 * asks which grid cell that pulled position lands in. Lines therefore bend
 * continuously rather than translating, and the deformation is local — two
 * cells away the grid is exactly where it was.
 *
 * Pointer-reactive, so it opts into tracking. On a touch screen there is no
 * pointer and the grid rests at centre with only its idle wave running,
 * which is a reasonable thing to look at rather than a broken one.
 *
 * Anti-aliasing is by hand. `fwidth` needs `OES_standard_derivatives` on
 * WebGL 1, and a design that silently fails to compile on a driver without
 * it is worse than one whose lines are a shade soft.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const GRID_DISTORTION_PROGRAM: GLProgram = {
  id: 'grid-distortion',
  kind: 'webgl',
  speed: 1,
  pointer: true,
  light: { c0: '#0f172a', c1: '#6366f1', c2: '#e11d48', bg: '#f8fafc' },
  dark: { c0: '#64748b', c1: '#818cf8', c2: '#fb7185', bg: '#050810' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  vec2 m = aspect(u_pointer);

  vec2 d = p - m;
  float pull = exp(-dot(d, d) * 3.4);

  // Toward the pointer, hardest at the centre of the falloff. The epsilon
  // keeps normalize() defined at exactly the pointer's position.
  vec2 q = p - normalize(d + vec2(1e-5)) * pull * 0.34;

  // A slow idle wave so the grid is alive before anyone touches it.
  q += 0.045 * vec2(sin(q.y * 2.0 + u_time * 0.4), cos(q.x * 2.0 - u_time * 0.3));

  float cells = 14.0;
  vec2 g = q * cells;
  vec2 f = abs(fract(g) - 0.5);
  float line = min(f.x, f.y);

  // Line width in cell units, widened by roughly one device pixel.
  float aa = 1.6 * cells / u_resolution.y;
  float grid = 1.0 - smoothstep(0.018, 0.018 + aa * 2.0, line);

  vec3 col = mix(u_bg, mix(u_c0, u_c1, pull), grid);
  col += u_c2 * pull * grid * 0.55;

  // The lens itself, faintly, so the distortion has a source.
  col += u_c1 * pull * 0.10;

  return vec4(col, 1.0);
}
`,
}

export function GridDistortion({ className }: { className?: string }) {
  return <ShaderSurface program={GRID_DISTORTION_PROGRAM} className={className} />
}

ripple-grid.source:
'use client'

/**
 * Ripple Grid — a lattice of dots that swells with concentric waves.
 *
 * The grid stays put and the *dots* change size, which is the opposite
 * choice from `grid-distortion` and reads completely differently: a
 * distorted grid looks like a lens, a pulsing one looks like a surface
 * responding. Two waves drive it — a slow one from the centre that never
 * stops, and a tighter ring around the pointer that arrives when it does.
 *
 * Each dot samples the wave at its own cell centre rather than per pixel,
 * so a dot is one size all over instead of being a smooth blob — that is
 * what keeps it reading as a grid of elements and not as a gradient with
 * holes in it.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import type { GLProgram } from './shader-runtime'

export const RIPPLE_GRID_PROGRAM: GLProgram = {
  id: 'ripple-grid',
  kind: 'webgl',
  speed: 1,
  pointer: true,
  light: { c0: '#2563eb', c1: '#7c3aed', c2: '#06b6d4', bg: '#f1f5f9' },
  dark: { c0: '#3b82f6', c1: '#a855f7', c2: '#22d3ee', bg: '#04070f' },
  fragment: `
vec4 render(vec2 uv) {
  vec2 p = aspect(uv);
  vec2 m = aspect(u_pointer);

  float cells = 22.0;
  vec2 g = p * cells;
  vec2 id = floor(g);
  vec2 c = fract(g) - 0.5;

  // The cell's centre, back in aspect space. Sampling the waves here and
  // not at the pixel is what makes each dot a single uniform size.
  vec2 centre = (id + 0.5) / cells;

  float r1 = length(centre);
  float r2 = length(centre - m);

  float wave = 0.5 + 0.5 * sin(r1 * 7.0 - u_time * 1.5);
  float ring = exp(-r2 * r2 * 4.5) * (0.5 + 0.5 * sin(r2 * 15.0 - u_time * 3.0));

  float amp = clamp(wave * 0.55 + ring * 0.85, 0.0, 1.0);

  float d = length(c);
  float radius = 0.10 + 0.34 * amp;
  float dotMask = smoothstep(radius, radius - 0.06, d);

  vec3 col = mix(u_bg, mix(u_c0, u_c1, amp), dotMask);
  col += u_c2 * dotMask * ring * 0.75;

  return vec4(col, 1.0);
}
`,
}

export function RippleGrid({ className }: { className?: string }) {
  return <ShaderSurface program={RIPPLE_GRID_PROGRAM} className={className} />
}

ascii-rain.source:
'use client'

/**
 * ASCII Rain — a noise field resolved as monospace glyphs.
 *
 * 2D canvas rather than a shader, deliberately. A fragment shader can draw
 * ASCII by packing 5×7 bitmaps into integers and unpacking them per pixel;
 * the result works and is unreadable, and changing the character ramp means
 * re-deriving a table of magic numbers. Here the ramp is a string, the font
 * is the font, and anybody can swap either.
 *
 * Two fields are summed. A slow fbm gives the drifting mass that makes the
 * screen look like something rather than static, and a per-column "drop"
 * term — a bright head with a decaying tail — gives the rain. The ramp is
 * ordered by ink coverage, so brightness maps to how much of the cell is
 * filled, which is the whole trick behind ASCII art.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import { fbm2D, hash2D, type Canvas2DProgram } from './shader-runtime'

/** Ordered by ink coverage, lightest first. */
const RAMP = ' .:-=+*#%@'

/** Cell size in CSS pixels. Also the font size, near enough, for monospace. */
const CELL_W = 9
const CELL_H = 13

interface Column {
  /** Where this column's drop head is, in cells. */
  head: number
  speed: number
  length: number
}

export const ASCII_RAIN_PROGRAM: Canvas2DProgram = {
  id: 'ascii-rain',
  kind: 'canvas',
  speed: 1,
  light: { c0: '#94a3b8', c1: '#0f172a', c2: '#16a34a', bg: '#f8fafc' },
  dark: { c0: '#14532d', c1: '#4ade80', c2: '#dcfce7', bg: '#020803' },

  init: (frame) => {
    const cols = Math.ceil(frame.width / CELL_W)
    const rows = Math.ceil(frame.height / CELL_H)
    const columns: Column[] = []
    for (let i = 0; i < cols; i++) {
      columns.push({
        // Seeded from the column index, not from Math.random(), so a card
        // that re-seeds on resize does not visibly reshuffle.
        head: hash2D(i, 7) * rows * 2,
        speed: 4 + hash2D(i, 13) * 14,
        length: 5 + Math.floor(hash2D(i, 29) * 14),
      })
    }
    return { columns, rows, cols }
  },

  draw: (ctx, frame, state) => {
    const { columns, rows, cols } = state as { columns: Column[]; rows: number; cols: number }
    const { palette, time } = frame

    ctx.font = `${CELL_H - 1}px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace`
    ctx.textBaseline = 'top'

    for (let x = 0; x < cols; x++) {
      const col = columns[x]
      // The head wraps through twice the height so there is a gap between
      // one drop leaving and the next arriving.
      const head = (col.head + time * col.speed) % (rows * 2)

      for (let y = 0; y < rows; y++) {
        // Ambient: the slow field everything sits in.
        const ambient = fbm2D(x * 0.12, y * 0.12 - time * 0.35) * 0.55

        // The drop: 1 at the head, decaying back up the column.
        const behind = head - y
        const drop =
          behind >= 0 && behind < col.length ? 1 - behind / col.length : 0

        const v = ambient + drop * 0.9
        if (v < 0.18) continue

        const idx = Math.min(RAMP.length - 1, Math.floor(v * RAMP.length))
        // The glyph is chosen by brightness but jittered per cell over
        // time, so a flat region shimmers instead of showing one repeated
        // character in a block.
        const jitter = Math.floor(hash2D(x, y + Math.floor(time * 6)) * 2)
        const ch = RAMP[Math.max(0, Math.min(RAMP.length - 1, idx + jitter - 1))]

        // Three bands rather than a continuous ramp: the head is the
        // accent, the tail the primary, the ambient field the muted one.
        ctx.fillStyle = drop > 0.75 ? palette.c2 : drop > 0.1 ? palette.c1 : palette.c0
        ctx.globalAlpha = Math.min(1, 0.25 + v)
        ctx.fillText(ch, x * CELL_W, y * CELL_H)
      }
    }

    ctx.globalAlpha = 1
  },
}

export function AsciiRain({ className }: { className?: string }) {
  return <ShaderSurface program={ASCII_RAIN_PROGRAM} className={className} />
}

particle-drift.source:
'use client'

/**
 * Particle Drift — a constellation that leans toward the pointer.
 *
 * The other 2D design, and here for the reason a particle system is always
 * a particle system: the state has to survive between frames. A shader gets
 * one function of position and time and nothing else, so a particle in a
 * shader is a particle whose whole history has to be re-derivable from its
 * index — which rules out the links, because whether two particles are near
 * each other is a fact about this frame that has to be measured.
 *
 * The links are the effect. Dots drifting alone are dust; dots that draw a
 * line when they come within range read as a network, which is why every
 * "connections" hero on the internet looks like this.
 */

import * as React from 'react'

import { ShaderSurface } from './shader-surface'
import { hash2D, type Canvas2DProgram } from './shader-runtime'

/**
 * Enough to read as a field, few enough that the O(n²) link pass is free.
 *
 * 64 particles is 2,016 distance checks a frame — about 30 µs. Doubling the
 * count quadruples that, and the visual difference is "busier", so the cap
 * is here rather than in a spatial index nobody needs.
 */
const COUNT = 64

/** Links draw below this distance, in CSS pixels, fading as they stretch. */
const LINK_DIST = 96

interface Particle {
  x: number
  y: number
  vx: number
  vy: number
  r: number
}

export const PARTICLE_DRIFT_PROGRAM: Canvas2DProgram = {
  id: 'particle-drift',
  kind: 'canvas',
  speed: 1,
  pointer: true,
  light: { c0: '#6366f1', c1: '#94a3b8', c2: '#ec4899', bg: '#f8fafc' },
  dark: { c0: '#818cf8', c1: '#334155', c2: '#f472b6', bg: '#03050d' },

  init: (frame) => {
    const particles: Particle[] = []
    for (let i = 0; i < COUNT; i++) {
      particles.push({
        x: hash2D(i, 1) * frame.width,
        y: hash2D(i, 2) * frame.height,
        // Slow: a field that crosses the card in a few seconds reads as
        // traffic, and this is meant to sit behind text.
        vx: (hash2D(i, 3) - 0.5) * 22,
        vy: (hash2D(i, 4) - 0.5) * 22,
        r: 1 + hash2D(i, 5) * 1.8,
      })
    }
    return { particles, last: 0 }
  },

  draw: (ctx, frame, state) => {
    const s = state as { particles: Particle[]; last: number }
    const { width, height, palette, pointer, time } = frame

    // The runtime hands out absolute time, not a delta, because a shader
    // has no use for one. Differencing it here keeps the motion
    // frame-rate-independent, and clamping covers the tab that was hidden
    // for a minute and came back.
    const dt = s.last === 0 ? 0 : Math.min(time - s.last, 0.1)
    s.last = time

    // Pointer is in GL orientation (y up); the canvas is y down.
    const px = pointer.x * width
    const py = (1 - pointer.y) * height

    for (const p of s.particles) {
      // A weak pull toward the pointer, capped by distance so particles
      // across the card are unaffected and nothing ever collapses onto it.
      const dx = px - p.x
      const dy = py - p.y
      const d2 = dx * dx + dy * dy
      const pull = 2600 / Math.max(d2, 2600)
      p.vx += dx * pull * dt * 0.9
      p.vy += dy * pull * dt * 0.9

      // Drag, so the pull cannot accumulate into orbit.
      p.vx *= 1 - 0.55 * dt
      p.vy *= 1 - 0.55 * dt

      p.x += p.vx * dt
      p.y += p.vy * dt

      // Wrap rather than bounce: a bounce puts a visible wall at the edge
      // of a surface that is supposed to look like a window onto something.
      if (p.x < -10) p.x = width + 10
      if (p.x > width + 10) p.x = -10
      if (p.y < -10) p.y = height + 10
      if (p.y > height + 10) p.y = -10
    }

    /* -- Links, under the dots ------------------------------------- */

    ctx.lineWidth = 1
    for (let i = 0; i < s.particles.length; i++) {
      const a = s.particles[i]
      for (let j = i + 1; j < s.particles.length; j++) {
        const b = s.particles[j]
        const dx = a.x - b.x
        const dy = a.y - b.y
        const d = Math.sqrt(dx * dx + dy * dy)
        if (d > LINK_DIST) continue
        ctx.globalAlpha = (1 - d / LINK_DIST) * 0.5
        ctx.strokeStyle = palette.c1
        ctx.beginPath()
        ctx.moveTo(a.x, a.y)
        ctx.lineTo(b.x, b.y)
        ctx.stroke()
      }
    }

    /* -- Dots ------------------------------------------------------- */

    for (const p of s.particles) {
      const near = Math.hypot(px - p.x, py - p.y) < LINK_DIST
      ctx.globalAlpha = near ? 1 : 0.8
      ctx.fillStyle = near ? palette.c2 : palette.c0
      ctx.beginPath()
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
      ctx.fill()
    }

    ctx.globalAlpha = 1
  },
}

export function ParticleDrift({ className }: { className?: string }) {
  return <ShaderSurface program={PARTICLE_DRIFT_PROGRAM} className={className} />
}
